/*
 * Reference clock output: a free-running 48 MHz square wave on GPIO17,
 * generated by the I2S0 MCLK divider from PLL240M (240 MHz / 5, pure integer
 * divide -- no fractional dither, so no spurs near the carrier).
 *
 * This is fully independent of the video engine: video uses the LCD_CAM
 * peripheral, this uses I2S0, and GPIO17 is otherwise unused. Once started the
 * clock free-runs in hardware and needs no CPU attention.
 *
 * (Technique validated in the ~/esp/tv-freq scratch project: PLL240M is an
 * undocumented tx_clk_sel value the IDF driver won't select, so it is set here
 * by hand. The /240 = 1.000 MHz liveness test in that project confirmed the mux
 * input is live before trusting the /5 = 48 MHz divide.)
 */
#pragma once

#include <stdbool.h>

/* Configure I2S0 and drive 48 MHz out GPIO17. Returns once the clock is live. */
void clkout_start_48mhz(void);

/* Turn the carrier on the pin off/on (glitch-free; the I2S clock keeps running,
 * only the pin routing changes). */
void clkout_set_enabled(bool on);

/* Power the mixer/modulator rail. Q4 (P-FET, gate on GPIO44 = MIXER_SHUTDOWN)
 * feeds MIXER_3V3 from +3V3; R35 (100k) holds the gate up so the rail is OFF
 * at reset and stays off unless we pull the gate low. Nothing drove this pin
 * before, so the RF chain was unpowered on the assembled board.
 *
 * NOTE GPIO44 is U0RXD: this only works with the console on USB-Serial/JTAG. */
void mixer_set_enabled(bool on);

/* Start a background task that toggles the carrier each time BOOT (GPIO0) is
 * pressed. Call after clkout_start_48mhz(). */
void clkout_enable_boot_toggle(void);
